const STORY_IDS=new Set(['signal-start','garden-sample','west-marker','bamboo-echo','north-beacon','okpo-current','port-lens','ilun-bloom','south-source','league-open','signal-restored','postgame-call','whole-island']);
const LEAGUE_IDS=new Set(['reef','forest','sky','tide','champion']);
const GYM_REGION_IDS=new Set(REGIONS.filter(r=>r.badge).map(r=>r.id));
const cleanStringArray=(value,max,allowed,error)=>{if(!Array.isArray(value)||value.length>max||value.some(x=>typeof x!=='string'||x.length>40||allowed&&!allowed.has(x)))throw Error(error);return [...new Set(value)]};
function cleanGymPuzzles(value){if(value==null)return {};if(!value||typeof value!=='object'||Array.isArray(value))throw Error('체육관 퍼즐 기록 오류');const out={};for(const [id,row] of Object.entries(value)){if(!GYM_REGION_IDS.has(id)||!row||typeof row!=='object'||Array.isArray(row)||!Number.isInteger(row.moves)||row.moves<0||row.moves>9999||typeof row.solved!=='boolean')throw Error('체육관 퍼즐 기록 오류');const clean={moves:row.moves,solved:row.solved};if(row.bits!==undefined){if(!Array.isArray(row.bits)||row.bits.length>4||row.bits.some(x=>typeof x!=='boolean'))throw Error('체육관 퍼즐 기록 오류');clean.bits=[...row.bits]}if(row.position!==undefined){if(typeof row.position!=='string'||row.position.length>20)throw Error('체육관 퍼즐 기록 오류');clean.position=row.position}if(row.rotations!==undefined){if(!Array.isArray(row.rotations)||row.rotations.length>3||row.rotations.some(x=>!Number.isInteger(x)||x<0||x>3))throw Error('체육관 퍼즐 기록 오류');clean.rotations=[...row.rotations]}if(row.sequence!==undefined){if(!Array.isArray(row.sequence)||row.sequence.length>5||row.sequence.some(x=>typeof x!=='string'||x.length>10))throw Error('체육관 퍼즐 기록 오류');clean.sequence=[...row.sequence]}out[id]=clean}return out}
function cleanGymTrainers(value){if(value==null)return {};if(!value||typeof value!=='object'||Array.isArray(value))throw Error('체육관 트레이너 기록 오류');const out={};for(const [id,rows] of Object.entries(value)){if(!GYM_REGION_IDS.has(id))throw Error('체육관 트레이너 기록 오류');out[id]=cleanStringArray(rows,6,null,'체육관 트레이너 기록 오류');if(out[id].some(x=>!/^[a-z0-9-]+$/.test(x)))throw Error('체육관 트레이너 기록 오류')}return out}

export function freshJourney(){return {region:'gohyeon',visited:['gohyeon'],observed:[],hiddenItems:[],rivals:[],gymPuzzles:{},gymTrainers:{},story:[],league:[],rod:false,bike:false,cycling:false,boat:false,surf:false,champion:false,legendsSeen:[],legendsCaught:[],opening:'first-battle',playSeconds:0}}
export function cleanJourney(value){
 const j={...freshJourney(),...(value??{}),opening:value?.opening??'complete'};
 if(!REGION_BY_ID[j.region])throw Error('지역 정보 오류');
 for(const k of ['visited','observed','hiddenItems'])if(!Array.isArray(j[k])||j[k].length>20||j[k].some(id=>!REGION_BY_ID[id]))throw Error('탐험 기록 오류');
 if(!Array.isArray(j.rivals)||j.rivals.length>6||j.rivals.some(id=>!['first','north','port','south','final','postgame'].includes(id)))throw Error('라이벌 기록 오류');
 if(!Number.isFinite(j.playSeconds)||j.playSeconds<0||j.playSeconds>1e9)throw Error('플레이 시간 오류');
 if(!Array.isArray(j.legendsSeen)||!Array.isArray(j.legendsCaught)||j.legendsSeen.length>7||j.legendsCaught.length>7||[...j.legendsSeen,...j.legendsCaught].some(id=>!Number.isInteger(id)||id<145||id>151))throw Error('특별 생태몬 기록 오류');
 if(!['first-battle','complete'].includes(j.opening))throw Error('인트로 진행 기록 오류');
 return {region:j.region,visited:[...new Set(j.visited)],observed:[...new Set(j.observed)],hiddenItems:[...new Set(j.hiddenItems)],rivals:[...new Set(j.rivals)],gymPuzzles:cleanGymPuzzles(j.gymPuzzles),gymTrainers:cleanGymTrainers(j.gymTrainers),story:cleanStringArray(j.story,STORY_IDS.size,STORY_IDS,'이야기 기록 오류'),league:cleanStringArray(j.league,LEAGUE_IDS.size,LEAGUE_IDS,'리그 기록 오류'),rod:!!j.rod,bike:!!j.bike,cycling:!!j.bike&&!!j.cycling,boat:!!j.boat,surf:!!j.surf,champion:!!j.champion,legendsSeen:[...new Set(j.legendsSeen)],legendsCaught:[...new Set(j.legendsCaught)],opening:j.opening,playSeconds:Math.floor(j.playSeconds)};
}
